window.__GUIDE_CHUNKS__.push([{"id": "21-007", "chapter_num": 21, "chapter_title": "Travelling Abroad and Staying Safe", "chapter_file": "21-travelling-abroad.md", "number": 7, "title": "Check your immigration consultant on the public register before paying", "money": "0", "time": "low", "willpower": "no", "benefit": "mid", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "Nothing; a name search on the register.", "plain": "Only licensed consultants may represent you before Immigration Canada. Look up the consultant's name on the College of Immigration and Citizenship Consultants public register before signing and paying. An unlicensed ghost consultant can take your money and file nothing, leaving you with a refused application and no recourse.", "benefit_text": "The CICC public register confirms a consultant's licence in seconds; skipping the check is the classic way to lose thousands to a ghost consultant.", "sources": "College of Immigration and Citizenship Consultants — statutory regulator and public register — https://college-ic.ca/ICCRC/Assets/Documents/College%20of%20Immigration%20and%20Citizenship%20Consultants-EN.pdf", "notes": "The College is the statutory regulator under federal law; its register of licensees is public and kept up to date.", "urls": ["https://college-ic.ca/ICCRC/Assets/Documents/College%20of%20Immigration%20and%20Citizenship%20Consultants-EN.pdf"]}, {"id": "21-008", "chapter_num": 21, "chapter_title": "Travelling Abroad and Staying Safe", "chapter_file": "21-travelling-abroad.md", "number": 8, "title": "Get your international driving permit from CAA before driving abroad", "money": "low", "time": "low", "willpower": "no", "benefit": "low", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "The permit fee plus passport photos.", "plain": "Many countries require an international driving permit alongside your provincial licence. In Canada only CAA may issue the permit, under a United Nations mandate — any other seller is selling a fake. Apply at a CAA store with your licence and passport photos; you must be eighteen and older and hold a valid licence.", "benefit_text": "The CAA permit costs $32 plus tax and stays valid for one year; driving without one where it is required risks fines and a voided rental insurance.", "sources": "CAA — International Driving Permit — https://www.caa.ca/services/travel/international-driving-permit/", "notes": "", "urls": ["https://www.caa.ca/services/travel/international-driving-permit/"]}, {"id": "21-009", "chapter_num": 21, "chapter_title": "Travelling Abroad and Staying Safe", "chapter_file": "21-travelling-abroad.md", "number": 9, "title": "Carry passport copies and share your itinerary", "money": "0", "time": "low", "willpower": "no", "benefit": "low", "dimension": "time", "evidence": "B", "grade": "B", "disputed": false, "cost": "Nothing; a photocopy and a phone photo.", "plain": "Keep a paper copy and a phone photo of your passport's photo page separate from the passport itself, and leave your itinerary with someone at home. When the passport is lost and stolen, the copy speeds up the emergency replacement at the nearest Canadian office.", "benefit_text": "Copies plus a shared itinerary turn a lost passport from a trip-ending crisis into a same-week replacement.", "sources": "Global Affairs Canada — consular assistance, emergency info — https://travel.gc.ca/assistance/emergency-info", "notes": "", "urls": ["https://travel.gc.ca/assistance/emergency-info"]}, {"id": "22-001", "chapter_num": 22, "chapter_title": "How to rest", "chapter_file": "22-how-to-rest.md", "number": 1, "title": "Move your body to rest your mind", "money": "0", "time": "mid", "willpower": "some", "benefit": "high", "dimension": "freedom", "evidence": "A", "grade": "A", "disputed": false, "cost": "Free. It costs time and the will to start — the two scarcest things when you are low.", "plain": "Rest is not only lying still. Brisk walking and jogging lift low mood the most, with yoga and strength training close behind, and harder effort beats gentle effort. A short daily walk counts as rest for the mind.", "benefit_text": "Noetel et al., 2024, pooling 218 randomized trials with 14,170 people: walking or jogging versus depression, g = -0.62; yoga, g = -0.55; strength training, g = -0.49; higher intensity worked better. See also 3.5 on exercise and mood.", "sources": "https://doi.org/10.1136/bmj-2023-075847", "notes": "", "urls": ["https://doi.org/10.1136/bmj-2023-075847"]}, {"id": "22-002", "chapter_num": 22, "chapter_title": "How to rest", "chapter_file": "22-how-to-rest.md", "number": 2, "title": "Try a mindfulness course for anxiety before adding another pill", "money": "low", "time": "mid", "willpower": "some", "benefit": "high", "dimension": "freedom", "evidence": "B", "grade": "B", "disputed": false, "cost": "A course fee or a free app; eight weeks of practice, about an hour a day.", "plain": "An eight-week mindfulness course calmed anxiety about as well as a standard antidepressant in a head-to-head trial. It is not a replacement for medication that already works, but it is a real option to discuss with the doctor.", "benefit_text": "Hoge et al., JAMA Psychiatry 2023: 276 adults with anxiety disorders; 8 weeks of mindfulness-based stress reduction versus escitalopram 10–20 mg per day; anxiety scores fell about 30% in both groups, with MBSR non-inferior to the drug. DOI 10.1001/jamapsychiatry.2022.3679.", "sources": "https://doi.org/10.1001/jamapsychiatry.2022.3679", "notes": "", "urls": ["https://doi.org/10.1001/jamapsychiatry.2022.3679"]}, {"id": "22-003", "chapter_num": 22, "chapter_title": "How to rest", "chapter_file": "22-how-to-rest.md", "number": 3, "title": "Breathe out slowly when stress spikes", "money": "0", "time": "low", "willpower": "no", "benefit": "mid", "dimension": "freedom", "evidence": "B", "grade": "B", "disputed": false, "cost": "Free. Five minutes, anywhere.", "plain": "A few minutes a day of slow breathing with long out-breaths — in through the nose, out slowly through the mouth — lifted mood and slowed breathing more than the same minutes of meditation in one trial. It is free, it takes five minutes, and it works anywhere.", "benefit_text": "Balban et al., Cell Reports Medicine 2023: 5 minutes a day of cyclic sighing (extended exhales) for 28 days improved mood and reduced respiratory rate more than matched mindfulness meditation. DOI 10.1016/j.xcrm.2022.100895.", "sources": "https://doi.org/10.1016/j.xcrm.2022.100895 ; full text verified 2026-10-01: https://pmc.ncbi.nlm.nih.gov/articles/PMC9873947/", "notes": "", "urls": ["https://doi.org/10.1016/j.xcrm.2022.100895", "https://pmc.ncbi.nlm.nih.gov/articles/PMC9873947/"]}, {"id": "22-004", "chapter_num": 22, "chapter_title": "How to rest", "chapter_file": "22-how-to-rest.md", "number": 4, "title": "Treat loneliness as the health risk it is", "money": "0", "time": "mid", "willpower": "some", "benefit": "high", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "Free in money; it costs time and the courage to reach out first.", "plain": "Loneliness shortens life. People with strong social ties live longer, with an effect size researchers compare to the gap between smokers and non-smokers. Calling a friend is health care.", "benefit_text": "Holt-Lunstad et al., 2015, pooling 70 studies with 3.4 million people: social isolation, loneliness, and living alone raised the likelihood of mortality (OR 1.29, 1.26, and 1.32) — on par with smoking and heavier than obesity. PMID 25910392.", "sources": "https://pubmed.ncbi.nlm.nih.gov/25910392/", "notes": "", "urls": ["https://pubmed.ncbi.nlm.nih.gov/25910392/"]}, {"id": "22-005", "chapter_num": 22, "chapter_title": "How to rest", "chapter_file": "22-how-to-rest.md", "number": 5, "title": "Spend time in green space", "money": "0", "time": "mid", "willpower": "no", "benefit": "mid", "dimension": "freedom", "evidence": "B", "grade": "B", "disputed": false, "cost": "Free. A park, a trail, a tree-lined street.", "plain": "Living near greenery is tied to living longer. A large pooling of studies found lower early-death risk where neighbourhoods were greener. A regular walk in the park is rest with a side effect of health.", "benefit_text": "Rojas-Rueda et al., The Lancet Planetary Health 2019, pooling 9 cohort studies with over 8 million people: each 0.1-point rise in neighbourhood greenness (NDVI) within 500 m of home was linked to 4% lower premature mortality.", "sources": "Rojas-Rueda D et al. (2019). Green spaces and mortality: a systematic review and meta-analysis of cohort studies. The Lancet Planetary Health. <https://doi.org/10.1016/S2542-5196(19)30215-3>", "notes": "", "urls": ["https://doi.org/10.1016/S2542-5196(19"]}, {"id": "23-001", "chapter_num": 23, "chapter_title": "Skills worth learning", "chapter_file": "23-skills-worth-learning.md", "number": 1, "title": "Check the legal working age first", "money": "0", "time": "low", "willpower": "no", "benefit": "high", "dimension": "freedom", "evidence": "B", "grade": "B", "disputed": false, "cost": "No money. One minute to check your age against the rule.", "plain": "In Quebec, the minimum legal working age is 14, with school-year hour limits for workers 16 and under. In Ontario, there is no single minimum age, but under-16s face limits during school hours and near hazardous workplaces. An employer willing to break this rule will also skip the paperwork your rights depend on.", "benefit_text": "Quebec (2026): minimum legal working age 14 (CNESST); ages 14–16 capped at 17 hours a week during the school year, 10 hours Monday to Friday (Bill 19, in force 2023-09-01). Ontario: no general minimum age; under-16s restricted during school hours and around factories and hazardous workplaces — specifics UNVERIFIED at write time (no ontario.ca primary captured).", "sources": "https://www.cnesst.gouv.qc.ca/en/working-conditions/special-status/young-workers/young-people-under-14-years-age ; https://www.assnat.qc.ca/Media/Process.aspx?MediaId=ANQ.Vigie.Bll.DocumentGenerique_187745en&process=Default&token=ZyMoxNwUn8ikQ+TRKYwPCjWrKwg+vIv9rjij7p3xLGTZDmLVSmJLoqe/vG7/YWzz", "notes": "Ontario specifics UNVERIFIED. Freedom dimension graded high: illegal work voids the protections in the labour chapter.", "urls": ["https://www.assnat.qc.ca/Media/Process.aspx?MediaId=ANQ.Vigie.Bll.DocumentGenerique_187745en&process=Default&token=ZyMoxNwUn8ikQ+TRKYwPCjWrKwg+vIv9rjij7p3xLGTZDmLVSmJLoqe/vG7/YWzz", "https://www.cnesst.gouv.qc.ca/en/working-conditions/special-status/young-workers/young-people-under-14-years-age"]}, {"id": "23-002", "chapter_num": 23, "chapter_title": "Skills worth learning", "chapter_file": "23-skills-worth-learning.md", "number": 2, "title": "Each extra year of schooling lines up with longer life (disputed)", "money": "0", "time": "high", "willpower": "yes", "benefit": "high", "dimension": "death", "evidence": "A (disputed)", "grade": "A", "disputed": true, "cost": "No tuition in this item — the price is years of your life spent studying. See the student-aid item for the money side.", "plain": "Each extra year of schooling lines up with about 1.9% lower adult mortality. The link is strongest at ages 18 to 49 and weakest past 70. Correlation is not proof that schooling itself adds the years: people who stay in school tend to start out advantaged.", "benefit_text": "IHME-CHAIN (2024): systematic review and meta-analysis, 603 studies, 59 countries, 10,355 observations (1980–2023). Each additional year of education associated with 1.9% lower adult all-cause mortality (95% uncertainty interval 1.8–2.0); ages 18–49: 2.9% (2.8–3.0); ages 70+: 0.8% (0.6–1.0); no sex difference; no difference by socio-demographic index.", "sources": "https://doi.org/10.1016/S2468-2667(23)00306-7 ; PubMed — https://pubmed.ncbi.nlm.nih.gov/38278172/", "notes": "Disputed. The authors report publication bias (p<0.0001): positive-looking results are easier to publish. All included studies are observational; years of schooling are tangled with family background, region, and occupation, so the 1.9% cannot be read as \"one more year of school buys you 1.9% less mortality\". It supports \"more schooling lines up with longer life\", not a personal life-extension prescription. Kept per the adaptation decision (both sides shown).", "urls": ["https://doi.org/10.1016/S2468-2667(23", "https://pubmed.ncbi.nlm.nih.gov/38278172/"]}, {"id": "23-003", "chapter_num": 23, "chapter_title": "Skills worth learning", "chapter_file": "23-skills-worth-learning.md", "number": 3, "title": "One in three working-age Canadians holds a bachelor's degree", "money": "0", "time": "low", "willpower": "no", "benefit": "mid", "dimension": "money", "evidence": "A", "grade": "A", "disputed": false, "cost": "No money. One glance at the numbers below.", "plain": "In 2021, about one in three Canadians aged 25 to 64 held at least a bachelor's degree, up from about one in four in 2016. A bachelor's is common enough that lacking one is the rarer position in professional hiring.", "benefit_text": "StatCan, 2021 Census: 32.9% of people aged 25 to 64 held a bachelor's degree or higher, up 4.3 percentage points since 2016 (figures verified 2026-10-01).", "sources": "https://www150.statcan.gc.ca/n1/daily-quotidien/221130/mc-a002-eng.htm", "notes": "Scarcity cuts both ways: the census counts all adults 25–64, so among younger cohorts the bachelor's share is higher — do not over-read your edge. For the study-vs-work math, see the next items.", "urls": ["https://www150.statcan.gc.ca/n1/daily-quotidien/221130/mc-a002-eng.htm"]}, {"id": "23-004", "chapter_num": 23, "chapter_title": "Skills worth learning", "chapter_file": "23-skills-worth-learning.md", "number": 4, "title": "Student aid: do not price school at sticker price", "money": "0", "time": "low", "willpower": "no", "benefit": "mid", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "No money to apply. One application through your province's aid plan.", "plain": "For 2026-27, federal full-time student grants reach $4,200 a year and federal loans reach $300 a week, with zero federal interest. Ontario's OSAP and Quebec's AFE add provincial grants and loans on top, with amounts reset each school year. Apply before assuming you cannot afford school.", "benefit_text": "Canada Student Financial Assistance, 2026–27 (2026): full-time grants $4,200/year (up from $3,000); full-time loans $300/week (up from $210); 0% federal interest. Provincial top-ups via OSAP (Ontario) and AFE (Quebec) — yearly amounts UNVERIFIED at write time (they reset each school year).", "sources": "https://www.canada.ca/en/employment-social-development/news/2026/03/government-of-canada-extends-financial-supports-for-post-secondary-students.html", "notes": "Grants are not repaid; loans are. \"0% federal interest\" is the federal portion only. Benefit graded mid: four years of grants ≈ $16,800 plus interest-free borrowing, inside $5,000–$50,000.", "urls": ["https://www.canada.ca/en/employment-social-development/news/2026/03/government-of-canada-extends-financial-supports-for-post-secondary-students.html"]}, {"id": "23-005", "chapter_num": 23, "chapter_title": "Skills worth learning", "chapter_file": "23-skills-worth-learning.md", "number": 5, "title": "Skilled trades: apprenticeship plus the Red Seal ticket", "money": "0", "time": "low", "willpower": "no", "benefit": "mid", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "No money to look. Check your province's college programs and apprenticeship office.", "plain": "Skilled trades run on apprenticeship: paid on-the-job training plus classroom blocks, ending in a journeyperson ticket. The Red Seal endorsement lets that ticket travel across provinces. Colleges also run short diplomas tied to local hiring.", "benefit_text": "Canada (2026): the Interprovincial Standards Red Seal Program is a federal–provincial–territorial partnership covering designated trades; a Red Seal endorsement on a provincial journeyperson certificate signals national-standard skill mobility. Apprenticeship mixes paid work with technical training; exact ratios and in-school weeks vary by province and trade — UNVERIFIED at write time.", "sources": "https://www.canada.ca/en/employment-social-development/news/2026/03/workforce-training-in-quebec-governments-of-canada-and-quebec-announce-funding-for-sustainable-jobs.html", "notes": "Union halls and employers sponsor most apprenticeships; without a sponsor you cannot start the hours. Benefit graded mid: a journeyperson wage premium compounds past $5,000 quickly.", "urls": ["https://www.canada.ca/en/employment-social-development/news/2026/03/workforce-training-in-quebec-governments-of-canada-and-quebec-announce-funding-for-sustainable-jobs.html"]}, {"id": "23-006", "chapter_num": 23, "chapter_title": "Skills worth learning", "chapter_file": "23-skills-worth-learning.md", "number": 6, "title": "The study-vs-work calculation", "money": "0", "time": "low", "willpower": "no", "benefit": "mid", "dimension": "money", "evidence": "C", "grade": "C", "disputed": false, "cost": "No money. Half an hour with the numbers.", "plain": "Put both paths on paper. Early work buys a few years of entry-level pay, once. More schooling buys a yearly pay gap multiplied by the decades after. Subtract grants and aid first, then compare. The answer differs by person: high tuition plus a weak job match can genuinely lose.", "benefit_text": "Method: compare (a) 3 years of entry-level earnings now against (b) the annual earnings gap of the credential times 30–40 working years, minus tuition net of grants. Use the 9%-a-year global schooling return as a rough yardstick and Job Bank wage data for the specific occupation (see the related items).", "sources": "https://www.yt.jobbank.gc.ca/trend-analysis/search-wages/wage-methodology", "notes": "The China-source return figures (4.0%–10.2%, 1988–2001) are dropped: too old and too foreign to price Canadian decisions. The global 9% and Job Bank data replace them.", "urls": ["https://www.yt.jobbank.gc.ca/trend-analysis/search-wages/wage-methodology"]}, {"id": "23-007", "chapter_num": 23, "chapter_title": "Skills worth learning", "chapter_file": "23-skills-worth-learning.md", "number": 7, "title": "The 9%-a-year yardstick for schooling returns", "money": "0", "time": "low", "willpower": "no", "benefit": "high", "dimension": "money", "evidence": "A", "grade": "A", "disputed": false, "cost": "No money. Memorize one number and use it as a yardstick.", "plain": "Across 139 countries, each extra year of schooling lines up with about 9% higher personal earnings a year, with women's returns running above men's. This prices formal schooling, not a weekend course. Use it to interrogate training pitches: a $30,000 program should move earnings like a year of school.", "benefit_text": "Psacharopoulos and Patrinos (2018): review of 1,120 estimates across 139 countries (1950–2014). Global average private return to an additional year of schooling: about 9% per year; women's average returns persistently above men's; higher-education returns rising. A $30,000, six-month course should therefore be asked to move earnings like a full year of schooling.", "sources": "https://doi.org/10.1596/1813-9450-8402", "notes": "A global average hides wide gaps by field and country. Benefit graded high: 9% a year on a $50,000 salary is $4,500 a year, compounding past $50,000 over a working life.", "urls": ["https://doi.org/10.1596/1813-9450-8402"]}, {"id": "23-008", "chapter_num": 23, "chapter_title": "Skills worth learning", "chapter_file": "23-skills-worth-learning.md", "number": 8, "title": "Check the credential before you pay for it", "money": "0", "time": "low", "willpower": "no", "benefit": "mid", "dimension": "money", "evidence": "C", "grade": "C", "disputed": false, "cost": "No money. Fifteen minutes of checking before you pay.", "plain": "Before paying for any certificate, check whether the occupation is regulated and who licenses it. In the skilled trades, the Red Seal path runs through provincial apprenticeship offices. In professions like accounting, only the provincial regulator's designation counts. A private certificate is not a licence.", "benefit_text": "Canada (2026): regulated occupations are licensed province by province; only the regulator's credential authorizes the title and the work. Exact regulator lists and private-career-college verification steps are UNVERIFIED at write time. Rule of thumb: titles like electrician, nurse, and CPA are protected — training that does not end in the regulator's exam buys no legal right to the title.", "sources": "https://www.canada.ca/en/employment-social-development/news/2026/03/workforce-training-in-quebec-governments-of-canada-and-quebec-announce-funding-for-sustainable-jobs.html", "notes": "Fraud markers: a pass promised without your participation, income from hanging the certificate on a wall, fees for \"registration\" with no exam. Bought papers and ghostwritten applications get caught: regulators verify education directly with schools, and misrepresentation can void the credential plus trigger a fraud record. Exact penalty schedules by regulator are UNVERIFIED at write time. Benefit graded mid: avoiding a wasted $3,000–$10,000 program plus lost months.", "urls": ["https://www.canada.ca/en/employment-social-development/news/2026/03/workforce-training-in-quebec-governments-of-canada-and-quebec-announce-funding-for-sustainable-jobs.html"]}, {"id": "23-009", "chapter_num": 23, "chapter_title": "Skills worth learning", "chapter_file": "23-skills-worth-learning.md", "number": 9, "title": "Use public training money before your own", "money": "0", "time": "mid", "willpower": "some", "benefit": "mid", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "No money, sometimes much less. Training takes time. The hard part is checking the subsidy directory before impulse-buying a commercial course.", "plain": "Check public money before spending your own. The Canada Training Credit refunds $250 a year toward training fees, up to $5,000 over a lifetime, for workers aged 26 to 65. Provinces and employment centres run their own subsidized programs with yearly-changing lists. In a job, ask your employer about training funds first.", "benefit_text": "Canada Training Credit (2026): $250/year accumulation toward a $5,000 lifetime limit; ages 26–65; refundable credit claimed on the tax return (CRA line 45350). Provincial and territorial training subsidies and employment-centre programs exist with yearly-changing eligibility — specifics UNVERIFIED at write time.", "sources": "https://www.canada.ca/en/revenue-agency/services/tax/individuals/topics/about-your-tax-return/tax-return/completing-a-tax-return/deductions-credits-expenses/line-45350-canada-training-credit.html", "notes": "The credit offsets fees; it does not pay living costs while you train. Benefit graded mid: $5,000 lifetime sits at the mid boundary.", "urls": ["https://www.canada.ca/en/revenue-agency/services/tax/individuals/topics/about-your-tax-return/tax-return/completing-a-tax-return/deductions-credits-expenses/line-45350-canada-training-credit.html"]}, {"id": "23-010", "chapter_num": 23, "chapter_title": "Skills worth learning", "chapter_file": "23-skills-worth-learning.md", "number": 10, "title": "Pick skills machines struggle with", "money": "0", "time": "low", "willpower": "no", "benefit": "high", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "No money. Run each skill idea through the three bottlenecks before committing.", "plain": "Machines struggle most with three things: fine physical dexterity, coming up with new ideas, and dealing with people. Work that needs a physical site, non-standard settings, and live judgment resists automation best. Routine information-processing jobs face the highest risk.", "benefit_text": "Frey and Osborne (2017): 702 US occupations scored for computerisation probability; about 47% of employment in the high-risk band. The engineering bottlenecks: perception and manipulation (finger and hand dexterity, awkward work), creative intelligence, social intelligence. Later task-level studies put the high-risk share much lower — the 47% is an occupation-level upper bound, not a forecast with a date.", "sources": "https://doi.org/10.1016/j.techfore.2016.08.019", "notes": "Use the bottlenecks, not the 47%: the number is the most-misused part of the paper. Benefit graded high: picking a durable trade shapes decades of earnings.", "urls": ["https://doi.org/10.1016/j.techfore.2016.08.019"]}, {"id": "23-011", "chapter_num": 23, "chapter_title": "Skills worth learning", "chapter_file": "23-skills-worth-learning.md", "number": 11, "title": "Learn whether the skill has a pay ladder", "money": "0", "time": "low", "willpower": "no", "benefit": "mid", "dimension": "money", "evidence": "C", "grade": "C", "disputed": false, "cost": "No money. One check before you commit months to a skill.", "plain": "Learn whether the skill has a pay ladder before you climb it. In unionized workplaces, the collective agreement ties pay to classification. In the skilled trades, the journeyperson ticket and Red Seal endorsement are the ladder. Skills with no grading and no gatekeeper rarely convert to raises on their own.", "benefit_text": "Canada (2026): no national \"eight-level worker\" system exists. Pay progression runs through (a) collective agreements in unionized workplaces, (b) the journeyperson/Red Seal path in designated trades, and (c) employer policy elsewhere. Exact premium figures by trade and province are UNVERIFIED at write time.", "sources": "https://www.canada.ca/en/employment-social-development/news/2026/03/workforce-training-in-quebec-governments-of-canada-and-quebec-announce-funding-for-sustainable-jobs.html", "notes": "China's \"new eight-level worker\" policy has no Canadian equivalent and is dropped. Benefit graded mid: a ticketed trade premium clears $5,000 a year quickly.", "urls": ["https://www.canada.ca/en/employment-social-development/news/2026/03/workforce-training-in-quebec-governments-of-canada-and-quebec-announce-funding-for-sustainable-jobs.html"]}, {"id": "23-012", "chapter_num": 23, "chapter_title": "Skills worth learning", "chapter_file": "23-skills-worth-learning.md", "number": 12, "title": "Price the trade on Job Bank, not on anecdotes", "money": "0", "time": "low", "willpower": "no", "benefit": "mid", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "No money. Check two public sources before trusting a salary rumour.", "plain": "Do not price a trade on internet anecdotes. Job Bank publishes wages and outlooks by occupation and region, built from official surveys. Treat posted salaries as asking prices and self-reported incomes as survivor stories: neither counts hours, commuting, seasonal gaps, and slow months.", "benefit_text": "Job Bank (2026): wage reports by occupation and region with published methodology; outlooks flag expected demand. Use them against training-provider claims. Posting prices and anecdotes are not demand data.", "sources": "https://www.yt.jobbank.gc.ca/trend-analysis/search-wages/wage-methodology", "notes": "Benefit graded mid: choosing a trade with real demand is worth far more than $5,000 over a career, and choosing badly costs as much.", "urls": ["https://www.yt.jobbank.gc.ca/trend-analysis/search-wages/wage-methodology"]}, {"id": "23-013", "chapter_num": 23, "chapter_title": "Skills worth learning", "chapter_file": "23-skills-worth-learning.md", "number": 13, "title": "Prefer short programs that end at a job posting", "money": "low", "time": "mid", "willpower": "some", "benefit": "mid", "dimension": "money", "evidence": "C", "grade": "C", "disputed": false, "cost": "Short-course tuition, modest. Weeks of your time. The hard part is stopping on schedule if no job appears.", "plain": "Prefer programs that end at a specific job posting. A course that takes a year and still needs \"more experience\" after graduation costs far more than its price tag. Write your exit rule before you enroll: if no work by a set date, stop.", "benefit_text": "Selection rule: the program should name the jobs its graduates apply for, with recent placement evidence you can check. Open-ended programs with no placement record fail the test regardless of price.", "sources": "https://www.yt.jobbank.gc.ca/trend-analysis/search-wages/wage-methodology", "notes": "Private career colleges are regulated by each province — exact verification steps UNVERIFIED at write time. Benefit graded mid: months of misdirected training cost more than $5,000 in forgone earnings.", "urls": ["https://www.yt.jobbank.gc.ca/trend-analysis/search-wages/wage-methodology"]}, {"id": "23-014", "chapter_num": 23, "chapter_title": "Skills worth learning", "chapter_file": "23-skills-worth-learning.md", "number": 14, "title": "Test yourself instead of re-reading", "money": "0", "time": "low", "willpower": "some", "benefit": "high", "dimension": "time", "evidence": "A", "grade": "A", "disputed": false, "cost": "No money, no extra time. Swap re-reading hours for self-testing hours. The hard part is facing what you got wrong.", "plain": "Close the book and test yourself instead of re-reading. Classroom testing lifts scores by a medium amount across hundreds of studies. Testing plus feedback beats re-reading for the same minutes spent. Read a section, write the points from memory, then check.", "benefit_text": "Yang et al. (2021): meta-analysis of 222 studies, 48,478 students; classroom testing improved achievement with a medium effect (g = 0.499). Dunlosky et al. (2013): practice testing and distributed practice rated highest utility of ten learning techniques across ages, abilities, and test formats.", "sources": "https://doi.org/10.1037/bul0000309 ; https://doi.org/10.1177/1529100612453266", "notes": "Benefit graded high for the time dimension: for a daily learner, the retained study hours compound daily — the closest thing to free study time.", "urls": ["https://doi.org/10.1037/bul0000309", "https://doi.org/10.1177/1529100612453266"]}, {"id": "23-015", "chapter_num": 23, "chapter_title": "Skills worth learning", "chapter_file": "23-skills-worth-learning.md", "number": 15, "title": "Space the hours across days", "money": "0", "time": "low", "willpower": "some", "benefit": "high", "dimension": "time", "evidence": "A", "grade": "A", "disputed": false, "cost": "No money, same total hours. Split three hours into three days instead of one night. The hard part is starting days early.", "plain": "Spread the same hours across days instead of cramming. Hundreds of experiments agree: spacing wins. Match the gap to the horizon: test tomorrow, review tonight; test in a month, space reviews across weeks.", "benefit_text": "Cepeda et al. (2006): meta-analysis of 317 experiments on the spacing effect; longer retention horizons call for longer gaps. Dunlosky et al. (2013): distributed practice rated highest utility of ten techniques.", "sources": "https://doi.org/10.1037/0033-2909.132.3.354 ; https://doi.org/10.1177/1529100612453266", "notes": "Pair with self-testing: spaced retrieval beats spaced re-reading. Cramming works for tomorrow and evaporates after.", "urls": ["https://doi.org/10.1037/0033-2909.132.3.354", "https://doi.org/10.1177/1529100612453266"]}, {"id": "23-016", "chapter_num": 23, "chapter_title": "Skills worth learning", "chapter_file": "23-skills-worth-learning.md", "number": 16, "title": "Highlighting and re-reading feel productive; they are not", "money": "0", "time": "low", "willpower": "some", "benefit": "mid", "dimension": "time", "evidence": "A", "grade": "A", "disputed": false, "cost": "No money — it saves time. The hard part is giving up the feeling of studying.", "plain": "Highlighting and re-reading feel productive and rank at the bottom of ten common techniques. Summarizing, keyword mnemonics, and imagery sit there too. They are not useless, just narrow: the same minutes buy more as self-tests.", "benefit_text": "Dunlosky et al. (2013): of ten learning techniques, practice testing and distributed practice rated high utility; elaborative interrogation, self-explanation, and interleaved practice moderate; summarization, highlighting, keyword mnemonic, imagery for text, and rereading rated low utility.", "sources": "https://doi.org/10.1177/1529100612453266", "notes": "Highlighting is fine as a marker for what to self-test later; the error is treating the marker as the learning. Benefit graded mid for time: the hours rescued are weekly, not daily.", "urls": ["https://doi.org/10.1177/1529100612453266"]}, {"id": "23-017", "chapter_num": 23, "chapter_title": "Skills worth learning", "chapter_file": "23-skills-worth-learning.md", "number": 17, "title": "Mix problem types instead of batching them", "money": "0", "time": "low", "willpower": "some", "benefit": "mid", "dimension": "time", "evidence": "A", "grade": "A", "disputed": false, "cost": "No money. Shuffle problem types instead of drilling one type twenty times. The hard part is tolerating lower scores during practice.", "plain": "Mix problem types instead of batching them. Interleaved practice beats blocked practice by a medium amount overall, strongest for visual and classification tasks, weaker for math, and reversed for vocabulary — memorize words in blocks.", "benefit_text": "Brunmair and Richter (2019): meta-analysis of 59 studies, 238 effect sizes; interleaved vs blocked practice g = 0.42 overall; drawing tasks g = 0.67; math g = 0.34; vocabulary favours blocking (g = -0.39).", "sources": "https://doi.org/10.1037/bul0000209", "notes": "Use interleaving where the skill is telling problem types apart — math procedures, diagnoses, which statute applies. Use blocking for pure memorization.", "urls": ["https://doi.org/10.1037/bul0000209"]}, {"id": "23-018", "chapter_num": 23, "chapter_title": "Skills worth learning", "chapter_file": "23-skills-worth-learning.md", "number": 18, "title": "Learning styles are preferences, not prescriptions", "money": "0", "time": "low", "willpower": "no", "benefit": "low", "dimension": "time", "evidence": "A", "grade": "A", "disputed": false, "cost": "No money. Just stop sorting courses by supposed style.", "plain": "The idea that visual learners need visual teaching has almost no support from properly designed experiments. People have preferences; preferences do not predict which teaching works. Skip paid style assessments.", "benefit_text": "Pashler et al. (2008): commissioned review; proving the matching hypothesis requires a specific crossover interaction; almost no such evidence found, several results running opposite. Conclusion: insufficient evidence to use learning-style assessments in education.", "sources": "https://doi.org/10.1111/j.1539-6053.2009.01038.x", "notes": "This does not debunk every version of the theory — most were never properly tested. It debunks spending money on matching. Benefit graded low for time: a one-time unlearning.", "urls": ["https://doi.org/10.1111/j.1539-6053.2009.01038.x"]}, {"id": "23-019", "chapter_num": 23, "chapter_title": "Skills worth learning", "chapter_file": "23-skills-worth-learning.md", "number": 19, "title": "Practice in the format you will be tested in", "money": "0", "time": "low", "willpower": "some", "benefit": "mid", "dimension": "time", "evidence": "A", "grade": "A", "disputed": false, "cost": "No money, no extra time. Change only the practice format. The hard part is figuring out how you will actually use the material.", "plain": "Test yourself the way you will be tested. Self-testing transfers to new question types, applied problems, and reasoning at a small-to-medium level. It barely transfers when question and answer are swapped, so practice both directions.", "benefit_text": "Pan and Rickard (2018): meta-analysis of 192 transfer effect sizes, 10,382 participants; testing vs restudying transfers with d = 0.40 (95% CI 0.31–0.50); strongest for new formats, application, inference, and medical diagnosis; weakest for swapped stimulus-response and never-tested material.", "sources": "https://doi.org/10.1037/bul0000151", "notes": "Decide the future use first — selecting on an exam, judging on site — then build practice in that format.", "urls": ["https://doi.org/10.1037/bul0000151"]}, {"id": "23-020", "chapter_num": 23, "chapter_title": "Skills worth learning", "chapter_file": "23-skills-worth-learning.md", "number": 20, "title": "Find your regulator before you pick training", "money": "0", "time": "low", "willpower": "no", "benefit": "low", "dimension": "time", "evidence": "C", "grade": "C", "disputed": false, "cost": "No money. One lookup before you spend on courses.", "plain": "Some job titles are legally protected and the list differs by province. Electrician, nurse, engineer, and accountant each answer to a provincial regulator. Training that does not end at that regulator's exam buys no right to the title. Find the regulator first, then choose the training.", "benefit_text": "Canada (2026): regulated occupations are licensed province by province; the regulator sets entry exams, experience, and good-character checks. Exact regulator directories are UNVERIFIED at write time.", "sources": "https://www.canada.ca/en/employment-social-development/news/2026/03/workforce-training-in-quebec-governments-of-canada-and-quebec-announce-funding-for-sustainable-jobs.html", "notes": "Worked example: accounting's CPA path runs through university education, the CPA Professional Education Program, supervised experience, and the Common Final Examination, administered province by province — entry and fee specifics UNVERIFIED at write time (no cpacanada.ca primary URL returned by search). Benefit graded low for time: one lookup that prevents months of wrong-direction study.", "urls": ["https://www.canada.ca/en/employment-social-development/news/2026/03/workforce-training-in-quebec-governments-of-canada-and-quebec-announce-funding-for-sustainable-jobs.html"]}, {"id": "23-021", "chapter_num": 23, "chapter_title": "Skills worth learning", "chapter_file": "23-skills-worth-learning.md", "number": 21, "title": "A new credential does not automatically raise your pay", "money": "0", "time": "low", "willpower": "no", "benefit": "low", "dimension": "money", "evidence": "C", "grade": "C", "disputed": false, "cost": "No money. One question to your manager before you enroll.", "plain": "A new credential does not automatically raise your pay. In unionized workplaces the agreement sets whether the ticket moves your classification. Elsewhere, ask your employer in writing whether the credential changes your pay before you spend on it.", "benefit_text": "Canada (2026): no general law links credentials to raises. Pay effects run through collective agreements, regulated fee or wage scales, and employer policy. Ask first; the answer differs by workplace.", "sources": "https://www.yt.jobbank.gc.ca/trend-analysis/search-wages/wage-methodology", "notes": "Benefit graded low for money: the item itself saves the cost of a useless credential, typically under $5,000.", "urls": ["https://www.yt.jobbank.gc.ca/trend-analysis/search-wages/wage-methodology"]}, {"id": "24-001", "chapter_num": 24, "chapter_title": "Seeing a doctor", "chapter_file": "24-seeing-a-doctor.md", "number": 1, "title": "Register for OHIP or RAMQ the week you arrive", "money": "0", "time": "low", "willpower": "no", "benefit": "high", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "Free to register. The price of delay is paying out of pocket for care you could have had covered.", "plain": "Ontario and Quebec both cover medically necessary care, but you have to sign up. Ontario removed its three-month waiting period; Quebec still has a wait of up to three months for newcomers, with children, pregnancy care, and a few other services covered during the wait. Apply in the first week so the clock starts.", "benefit_text": "Ontario: apply at ServiceOntario; coverage starts immediately since the 3-month wait was removed (removal year UNVERIFIED at write time); you must be physically present in Ontario for 153 days in any 12-month period. Quebec (RAMQ): newcomers may wait up to 3 months; children under 18 are exempt from the wait, and care for pregnancy, infectious disease, and domestic violence is covered during the wait. Quebec also requires prescription-drug coverage: the public plan premium runs $0 to $789 a year for July 2026 to June 2027, with a $21.25 monthly deductible and 30% coinsurance up to a monthly cap of $105.25.", "sources": "https://www.ontario.ca/page/apply-ohip-and-get-health-card and https://www.ramq.gouv.qc.ca/en/citizens/health-insurance/know-eligibility-conditions and https://www.ramq.gouv.qc.ca/en/citizens/health-insurance/health-prescription-drug-insurance ; drug-plan figures verified 2026-10-01 on RAMQ's official pages: https://www.ramq.gouv.qc.ca/en/citizens/prescription-drug-insurance/amount-pay-prescription-drugs ($21.25 deductible, 30% coinsurance, rates in effect July 1, 2026 to June 30, 2027) and https://www.ramq.gouv.qc.ca/en/citizens/prescription-drug-insurance/understand-pharmacy-invoice ($105.25 maximum monthly contribution)", "notes": "The $789 maximum annual premium (from 2026-07-01) is per RAMQ's June 2026 rate announcement, as carried in iA Financial Group's administrator communique (https://files.ia.ca/-/media/files/iactuel/pdfs/2026/07-juillet/comm_admin_ramq_2026_en_acc.pdf); RAMQ's own rates-in-effect page still displayed the previous $766 figure at check time.", "urls": ["https://files.ia.ca/-/media/files/iactuel/pdfs/2026/07-juillet/comm_admin_ramq_2026_en_acc.pdf", "https://www.ontario.ca/page/apply-ohip-and-get-health-card", "https://www.ramq.gouv.qc.ca/en/citizens/health-insurance/health-prescription-drug-insurance", "https://www.ramq.gouv.qc.ca/en/citizens/health-insurance/know-eligibility-conditions", "https://www.ramq.gouv.qc.ca/en/citizens/prescription-drug-insurance/amount-pay-prescription-drugs", "https://www.ramq.gouv.qc.ca/en/citizens/prescription-drug-insurance/understand-pharmacy-invoice"]}, {"id": "24-002", "chapter_num": 24, "chapter_title": "Seeing a doctor", "chapter_file": "24-seeing-a-doctor.md", "number": 2, "title": "Call 911 for emergencies and 811 for advice", "money": "0", "time": "low", "willpower": "no", "benefit": "high", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "Free. Both numbers cost nothing to call.", "plain": "Call 911 for anything that threatens life: chest pain, heavy bleeding, a fire. Call 811 for health advice on everything else: a fever that will not break, a rash you cannot identify, a medication question at midnight. The 811 service decides whether you need the emergency room.", "benefit_text": "CRTC 2021-191: 911 is Canada's emergency number; 811 connects to non-urgent health advice (teletriage) — nurse staffing and round-the-clock availability vary by province, so check the provincial 811 service. Quebec's 811 also routes to Info-Social for psychosocial help.", "sources": "https://CRTC.GC.CA/eng/archive/2021/2021-191.pdf", "notes": "", "urls": ["https://CRTC.GC.CA/eng/archive/2021/2021-191.pdf"]}, {"id": "24-003", "chapter_num": 24, "chapter_title": "Seeing a doctor", "chapter_file": "24-seeing-a-doctor.md", "number": 3, "title": "Get on the list for a family doctor; use walk-ins only as a bridge", "money": "0", "time": "mid", "willpower": "some", "benefit": "high", "dimension": "death", "evidence": "C", "grade": "C", "disputed": false, "cost": "Free. It costs patience — the wait for a match can be months.", "plain": "A family doctor who knows your history beats a different walk-in doctor every visit. Ontario runs Health Care Connect through 811; Quebec runs the family-doctor finder, the GAMF, online and by phone. Register, then use walk-in clinics only until the match comes.", "benefit_text": "Ontario: Health Care Connect (via 811 or the Ontario find-a-doctor page) matches unattached patients with family doctors and nurse practitioners. Quebec: register with the GAMF at Québec.ca/gamf or 1-877-644-4545 (a valid health card and Quebec address are required; children under 14 are registered by an adult). Walk-in clinics handle one-off problems but do not follow you over time.", "sources": "https://www.ontario.ca/page/find-family-doctor-or-nurse-practitioner and https://publications.msss.gouv.qc.ca/msss/fichiers/2018/18-949-01A.pdf", "notes": "", "urls": ["https://publications.msss.gouv.qc.ca/msss/fichiers/2018/18-949-01A.pdf", "https://www.ontario.ca/page/find-family-doctor-or-nurse-practitioner"]}, {"id": "24-004", "chapter_num": 24, "chapter_title": "Seeing a doctor", "chapter_file": "24-seeing-a-doctor.md", "number": 4, "title": "Save the poison number in your phone", "money": "0", "time": "low", "willpower": "no", "benefit": "high", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "Free. Thirty seconds to save the number.", "plain": "If someone swallows something they should not have — pills, cleaners, a plant — call poison control before driving anywhere. They will tell you what to do next and what to bring; most cases are handled by phone.", "benefit_text": "Canada's toll-free poison line, 1-844-764-7669 (1-844-POISON-X), routes to the local centre, free, 24 hours a day, 7 days a week; Quebec keeps its own line, 1-800-463-5060 (Centre antipoison du Québec).", "sources": "https://www.aboutkidshealth.ca/poison-information-centres-in-canada", "notes": "", "urls": ["https://www.aboutkidshealth.ca/poison-information-centres-in-canada"]}, {"id": "24-005", "chapter_num": 24, "chapter_title": "Seeing a doctor", "chapter_file": "24-seeing-a-doctor.md", "number": 5, "title": "Know what happens with no health card: expect a bill, except for refugees", "money": "high", "time": "low", "willpower": "no", "benefit": "mid", "dimension": "money", "evidence": "C", "grade": "C", "disputed": false, "cost": "Without coverage, a hospital visit can run into the thousands — which is exactly why registering early matters.", "plain": "Without a provincial health card, hospitals and clinics bill you directly, and the amounts are not small. Refugees and asylum seekers are the exception: the federal Interim Federal Health Program covers basic care while claims are processed.", "benefit_text": "Uninsured patients are billed at hospital rates, which run far above insured costs. The Interim Federal Health Program (IFHP) provides temporary basic health coverage to refugees, resettled refugees, and asylum seekers in Canada.", "sources": "https://www.canada.ca/en/immigration-refugees-citizenship/corporate/mandate/sustainable-development/seea-funding-interim-federal-health-program.html", "notes": "", "urls": ["https://www.canada.ca/en/immigration-refugees-citizenship/corporate/mandate/sustainable-development/seea-funding-interim-federal-health-program.html"]}, {"id": "24-006", "chapter_num": 24, "chapter_title": "Seeing a doctor", "chapter_file": "24-seeing-a-doctor.md", "number": 6, "title": "Keep your own medical file", "money": "0", "time": "low", "willpower": "some", "benefit": "mid", "dimension": "death", "evidence": "C", "grade": "C", "disputed": false, "cost": "Free. A list on paper or on your phone, updated after each visit.", "plain": "Bring a list of your drugs, allergies, past surgeries, and test results to every appointment. Clinics lose faxes and switch systems; the one record that follows you everywhere is the one you carry.", "benefit_text": "No trial measures \"bringing your own file,\" so this is the author's advice, graded accordingly. The Institute for Safe Medication Practices Canada tells patients to keep their medication record up to date and have a doctor, nurse, or pharmacist review all medications — because the list is what prevents drug errors and duplicate prescriptions.", "sources": "https://horizonnb.ca/wp-content/uploads/2022/03/5-Questions-to-Ask-About-Your-Medication-EN.pdf", "notes": "", "urls": ["https://horizonnb.ca/wp-content/uploads/2022/03/5-Questions-to-Ask-About-Your-Medication-EN.pdf"]}, {"id": "24-007", "chapter_num": 24, "chapter_title": "Seeing a doctor", "chapter_file": "24-seeing-a-doctor.md", "number": 7, "title": "Expect triage at the emergency room, not first-come-first-served", "money": "0", "time": "high", "willpower": "some", "benefit": "mid", "dimension": "time", "evidence": "B", "grade": "B", "disputed": false, "cost": "Free at the point of care; the price is waiting, sometimes for hours.", "plain": "Emergency rooms treat the sickest first. A sprained ankle that arrived at noon waits behind chest pain that arrived at two. If the staff say it is not an emergency, believe them and follow the referral instead of waiting six hours to hear the same thing.", "benefit_text": "Canadian emergency departments use the Canadian Triage and Acuity Scale (CTAS): a five-level system that sorts patients by urgency of need — from resuscitation (level 1) to non-urgent (level 5). Patients are seen in order of triage score, not arrival time, so a minor problem waits behind anything more urgent.", "sources": "http://mchp-appserv.cpe.umanitoba.ca/viewDefinition.php?definitionID=103880", "notes": "", "urls": ["http://mchp-appserv.cpe.umanitoba.ca/viewDefinition.php?definitionID=103880"]}, {"id": "24-008", "chapter_num": 24, "chapter_title": "Seeing a doctor", "chapter_file": "24-seeing-a-doctor.md", "number": 8, "title": "Treat walk-in clinics as a bridge, not a home", "money": "0", "time": "low", "willpower": "no", "benefit": "mid", "dimension": "death", "evidence": "C", "grade": "C", "disputed": false, "cost": "Free with a health card. The hidden cost is fragmentation: no one tracks your story.", "plain": "Walk-ins are built for one-off problems: a sore throat, a prescription refill, a form. They do not track your blood pressure over years, chase your test results, remind you about screening. Use them as a bridge while you wait for a family doctor, not as the destination.", "benefit_text": "Author advice, graded C: continuity of care — seeing the same clinician over time — is linked in observational research to fewer hospitalizations, but no trial randomizes \"walk-in versus family doctor.\" The practical point stands: no walk-in keeps your longitudinal record, so get on the list for a family doctor (see item 3).", "sources": "https://www.ontario.ca/page/find-family-doctor-or-nurse-practitioner", "notes": "", "urls": ["https://www.ontario.ca/page/find-family-doctor-or-nurse-practitioner"]}, {"id": "25-001", "chapter_num": 25, "chapter_title": "When Someone Dies", "chapter_file": "25-when-someone-dies.md", "number": 1, "title": "For a violent, sudden, or unexplained death, call 911 and notify the coroner", "money": "0", "time": "low", "willpower": "some", "benefit": "high", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "Nothing; the call is free.", "plain": "If the death was violent, accidental, suspicious, sudden, unexplained — if the person was found alone and the cause is unclear — call emergency services at once. Do not move the body; leave the scene untouched. The coroner and the police must be notified directly in these cases; it is not optional.", "benefit_text": "Ontario law lists the deaths that must be reported to a coroner, including deaths by violence, misadventure, negligence, during or following pregnancy, sudden unexpected deaths, and deaths from any cause other than disease; prompt reporting protects the investigation and the family.", "sources": "Coroners Act, R.S.O. 1990, c. C.37, s.10 (current consolidation) — https://www.ontario.ca/laws/statute/90c37", "notes": "", "urls": ["https://www.ontario.ca/laws/statute/90c37"]}, {"id": "25-002", "chapter_num": 25, "chapter_title": "When Someone Dies", "chapter_file": "25-when-someone-dies.md", "number": 2, "title": "Get the medical certificate of death before anything else moves", "money": "0", "time": "mid", "willpower": "no", "benefit": "high", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "Nothing; the certifying doctor or coroner completes it.", "plain": "Every later step — registration, the funeral, the estate — needs the medical certificate stating the cause of death. The doctor who treated the person completes it; if the coroner investigates, the coroner completes and signs it instead. Ask who is responsible for it on the first day so paperwork does not stall the funeral.", "benefit_text": "Without the signed medical certificate, the death cannot be registered and the funeral provider cannot proceed; sorting out who signs it early avoids days of delay.", "sources": "O. Reg. 144/17 (coroner completes and signs the medical certificate of death) — https://www.ontario.ca/laws/regulation/r17144", "notes": "", "urls": ["https://www.ontario.ca/laws/regulation/r17144"]}, {"id": "25-003", "chapter_num": 25, "chapter_title": "When Someone Dies", "chapter_file": "25-when-someone-dies.md", "number": 3, "title": "Register the death and order certified copies of the death certificate", "money": "low", "time": "mid", "willpower": "no", "benefit": "high", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "A fee per certified copy; registration itself is straightforward.", "plain": "Register the death with the provincial registrar — ServiceOntario in Ontario, the Directeur de l'etat civil in Quebec — and order several certified copies of the death certificate. Banks, insurers, pension plans, and government benefits each want an original, and reordering later costs time.", "benefit_text": "Quebec processes declarations in about twenty business days and entering the event is free; order more copies than you think you need, because every institution keeps one.", "sources": "Directeur de l'etat civil processing times — https://etatcivil.gouv.qc.ca/en/certificate-copy/processing-time.html ; O. Reg. 144/17 — https://www.ontario.ca/laws/regulation/r17144", "notes": "", "urls": ["https://etatcivil.gouv.qc.ca/en/certificate-copy/processing-time.html", "https://www.ontario.ca/laws/regulation/r17144"]}, {"id": "25-004", "chapter_num": 25, "chapter_title": "When Someone Dies", "chapter_file": "25-when-someone-dies.md", "number": 4, "title": "Use only a licensed funeral provider and get the price list in writing", "money": "low", "time": "mid", "willpower": "some", "benefit": "mid", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "Comparing two or three providers; no fee.", "plain": "Funeral providers must be licensed — in Ontario the Bereavement Authority licenses funeral establishments, directors, cemeteries, and crematoriums. Ask for an itemized price list before you agree to anything, decline package upgrades you did not ask for, and keep every receipt; grief is when upselling works best.", "benefit_text": "Licensed providers are subject to oversight and complaint processes; an itemized list lets you spot forced bundles and charges for items you never requested.", "sources": "Bereavement Authority of Ontario — https://thebao.ca/about-the-bao/", "notes": "Quebec's funeral-industry permit rules are UNVERIFIED in this edition — see docs/verification/25-when-someone-dies.md.", "urls": ["https://thebao.ca/about-the-bao/"]}, {"id": "25-005", "chapter_num": 25, "chapter_title": "When Someone Dies", "chapter_file": "25-when-someone-dies.md", "number": 5, "title": "Dispute the cause of death through the coroner, not the funeral home", "money": "0", "time": "mid", "willpower": "some", "benefit": "mid", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "Nothing; persistence.", "plain": "If you believe the stated cause of death is wrong, tell the coroner and the police immediately and ask what examination will be done. The coroner decides whether a post-mortem is held — the funeral home does not. Raise the question before burial, before cremation, because afterwards the evidence is gone.", "benefit_text": "A timely objection can trigger a coroner's investigation and post-mortem examination; after the funeral, disputing the cause becomes far harder and more expensive.", "sources": "Coroners Act, s.10 — https://www.ontario.ca/laws/statute/90c37/v26", "notes": "", "urls": ["https://www.ontario.ca/laws/statute/90c37/v26"]}, {"id": "25-006", "chapter_num": 25, "chapter_title": "When Someone Dies", "chapter_file": "25-when-someone-dies.md", "number": 6, "title": "Make a will the formal way: signed at the end, two witnesses", "money": "low", "time": "mid", "willpower": "some", "benefit": "high", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "A lawyer's fee for a proper will, or careful DIY following the formalities.", "plain": "In Ontario a formal will must be signed at its end, acknowledged before two witnesses present at the same time, and signed by those witnesses in your presence. A will that misses these steps can fail exactly when your family needs it. Quebec recognizes handwritten and notarial wills under its own civil-law formalities — follow those, not Ontario's.", "benefit_text": "A valid will lets you choose your executor, your heirs, and guardians for minor children; without one, the province's intestacy rules choose for you.", "sources": "Succession Law Reform Act, R.S.O. 1990, c. S.26, s.4 — http://ontario.ca/laws/statute/90s26/v10", "notes": "Quebec will formalities (holograph and notarial wills under the Civil Code) are UNVERIFIED against the official text in this edition — see docs/verification/25-when-someone-dies.md.", "urls": ["http://ontario.ca/laws/statute/90s26/v10"]}, {"id": "25-007", "chapter_num": 25, "chapter_title": "When Someone Dies", "chapter_file": "25-when-someone-dies.md", "number": 7, "title": "Die without a will and the law picks your heirs — unmarried partners get nothing", "money": "0", "time": "low", "willpower": "some", "benefit": "high", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "Nothing; the cost is what your family pays later.", "plain": "Without a will, the province's intestacy rules decide who gets what, and they do not care about your wishes. In Ontario a married spouse takes a preferential share off the top and splits the rest with the children. In both Ontario and Quebec, an unmarried partner inherits nothing under intestacy — no matter how long you lived together. If that shocks you, write a will.", "benefit_text": "Ontario's preferential share is $350,000 for deaths on or after March 1, 2021; knowing the default lets you decide whether it matches your wishes or you need a will to override it.", "sources": "Succession Law Reform Act, R.S.O. 1990, c. S.26, Part II (O. Reg. 54/95 sets the share) — http://ontario.ca/laws/statute/90s26/v10", "notes": "The Quebec intestacy split (surviving spouse one-third, children two-thirds) is UNVERIFIED against the official text in this edition — see docs/verification/25-when-someone-dies.md. The unmarried-partner exclusion is the load-bearing point in both provinces.", "urls": ["http://ontario.ca/laws/statute/90s26/v10"]}, {"id": "25-008", "chapter_num": 25, "chapter_title": "When Someone Dies", "chapter_file": "25-when-someone-dies.md", "number": 8, "title": "Claim the CPP death benefit and check the survivor's pension", "money": "0", "time": "mid", "willpower": "no", "benefit": "mid", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "An application form and supporting documents; no fee.", "plain": "When a Canada Pension Plan contributor dies, the estate can receive a one-time death benefit, and a surviving spouse, a common-law partner, may qualify for a monthly survivor's pension. The executor should apply quickly; if there is no estate, the person who paid the funeral, the spouse, next of kin, can apply in that order. Quebec contributors go through Retraite Quebec instead.", "benefit_text": "The CPP death benefit pays a basic amount of $2,500 plus a possible top-up of $2,500, for a maximum of $5,000 for deaths on or after January 1, 2025; the survivor's pension is a separate monthly payment worth applying for on its own.", "sources": "CPP death benefit — http://canada.ca/en/services/benefits/publicpensions/cpp/cpp-death-benefit", "notes": "", "urls": ["http://canada.ca/en/services/benefits/publicpensions/cpp/cpp-death-benefit"]}, {"id": "26-001", "chapter_num": 26, "chapter_title": "Running a website or platform", "chapter_file": "26-running-a-website.md", "number": 1, "title": "If you touch other people's money, use licensed rails or register", "money": "low", "time": "mid", "willpower": "no", "benefit": "high", "dimension": "freedom", "evidence": "B", "grade": "B", "disputed": false, "cost": "Payment-processor fees on each transaction; registration time if you become a money services business yourself.", "plain": "Running payments, currency exchange, crypto transfers for others can make you a money services business. Operating unregistered is an offence — let a licensed processor carry that risk instead of your company.", "benefit_text": "Avoids criminal liability under federal anti-money-laundering law; FINTRAC publishes exactly which businesses must register.", "sources": "https://fintrac-canafe.canada.ca/public/businesses-entreprises-eng", "notes": "", "urls": ["https://fintrac-canafe.canada.ca/public/businesses-entreprises-eng"]}, {"id": "26-002", "chapter_num": 26, "chapter_title": "Running a website or platform", "chapter_file": "26-running-a-website.md", "number": 2, "title": "Publish a real privacy policy — PIPEDA applies to most commercial sites", "money": "0", "time": "mid", "willpower": "no", "benefit": "mid", "dimension": "freedom", "evidence": "B", "grade": "B", "disputed": false, "cost": "No money for a self-written policy; a day to map what data you collect and why.", "plain": "If your site collects emails, accounts, analytics for business purposes, federal privacy law requires meaningful consent and a clear policy saying what you do with the data.", "benefit_text": "Avoids Privacy Commissioner investigations and the customer-trust collapse that follows a public complaint.", "sources": "https://www.priv.gc.ca/media/2038/guide_org_e.pdf?irpid=", "notes": "", "urls": ["https://www.priv.gc.ca/media/2038/guide_org_e.pdf?irpid="]}, {"id": "26-003", "chapter_num": 26, "chapter_title": "Running a website or platform", "chapter_file": "26-running-a-website.md", "number": 3, "title": "Report breaches that pose a real risk of significant harm", "money": "0", "time": "low", "willpower": "no", "benefit": "mid", "dimension": "freedom", "evidence": "B", "grade": "B", "disputed": false, "cost": "No money; the cost is the discipline to notify quickly instead of hiding the breach.", "plain": "When personal data goes missing and could hurt someone — through identity theft, fraud, humiliation — it must be reported to the Privacy Commissioner and the affected people, with records kept of every incident.", "benefit_text": "Mandatory breach reporting has applied since late 2018; failing to report compounds the original breach with a separate compliance failure.", "sources": "https://www.priv.gc.ca/media/2038/guide_org_e.pdf?irpid=", "notes": "UNVERIFIED — the November 1, 2018 start date had no captured primary URL at write time; see docs/verification/26-running-a-website.md.", "urls": ["https://www.priv.gc.ca/media/2038/guide_org_e.pdf?irpid="]}, {"id": "26-004", "chapter_num": 26, "chapter_title": "Running a website or platform", "chapter_file": "26-running-a-website.md", "number": 4, "title": "Get consent before commercial email — CASL has teeth", "money": "0", "time": "mid", "willpower": "no", "benefit": "mid", "dimension": "freedom", "evidence": "A", "grade": "A", "disputed": false, "cost": "No money; the work of rebuilding your list on opt-in consent and adding identification plus unsubscribe to every message.", "plain": "Every commercial electronic message needs consent, your identity, and a working unsubscribe. Bought lists are the classic violation.", "benefit_text": "Avoids administrative monetary penalties that can reach millions of dollars per violation, plus personal liability for directors and officers.", "sources": "http://crtc.gc.ca/eng/phone/telemarketing/politi.htm http://fightspam.gc.ca/eic/site/030.nsf/eng/home", "notes": "UNVERIFIED — the \"millions of dollars per violation\" penalty scale is from secondary summaries; confirm current penalty ceilings on crtc.gc.ca. See docs/verification/26-running-a-website.md.", "urls": ["http://crtc.gc.ca/eng/phone/telemarketing/politi.htm", "http://fightspam.gc.ca/eic/site/030.nsf/eng/home"]}, {"id": "26-005", "chapter_num": 26, "chapter_title": "Running a website or platform", "chapter_file": "26-running-a-website.md", "number": 5, "title": "Quebec visitors: Law 25 consent is stricter than PIPEDA", "money": "0", "time": "mid", "willpower": "no", "benefit": "mid", "dimension": "freedom", "evidence": "B", "grade": "B", "disputed": false, "cost": "No money for the policy changes; developer time for consent handling and breach-notification procedures.", "plain": "Quebec requires consent that is manifest, free, informed, and given for a specific purpose, plus a named privacy officer and breach notification to the regulator and affected people.", "benefit_text": "Avoids penalties that can reach $10 million or two percent of worldwide turnover.", "sources": "https://termageddon.com/quebec-law-25/ https://www.shredit.com/en-us/resource-center/info-sheets/understanding-quebecs-law-25-essential-guide-for-businesses", "notes": "UNVERIFIED — Law 25 specifics rest on secondary legal summaries at write time; confirm on the Commission d'accès à l'information's site. See docs/verification/26-running-a-website.md.", "urls": ["https://termageddon.com/quebec-law-25/", "https://www.shredit.com/en-us/resource-center/info-sheets/understanding-quebecs-law-25-essential-guide-for-businesses"]}, {"id": "26-006", "chapter_num": 26, "chapter_title": "Running a website or platform", "chapter_file": "26-running-a-website.md", "number": 6, "title": "Register for GST/HST once taxable sales pass $30,000", "money": "0", "time": "low", "willpower": "no", "benefit": "mid", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "No money to register; quarterly or annual filing time after that.", "plain": "Past thirty thousand dollars in taxable sales over four quarters, you must charge and remit GST/HST — including on digital sales to Canadians.", "benefit_text": "Avoids back-tax assessments with interest and penalties on every dollar of tax you should have collected.", "sources": "https://www.canada.ca/en/revenue-agency/news/cra-multimedia-library/businesses-video-gallery/what-to-expect-during-gst-hst-examination.html", "notes": "", "urls": ["https://www.canada.ca/en/revenue-agency/news/cra-multimedia-library/businesses-video-gallery/what-to-expect-during-gst-hst-examination.html"]}, {"id": "26-007", "chapter_num": 26, "chapter_title": "Running a website or platform", "chapter_file": "26-running-a-website.md", "number": 7, "title": "Keep business records for six years", "money": "0", "time": "low", "willpower": "no", "benefit": "mid", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "No money; storage space and the habit of keeping invoices, receipts, and contracts.", "plain": "CRA can ask for your books years later. If the records are gone, the reassessment is the tax authority's version of your business, not yours.", "benefit_text": "Six years from the end of the taxation year is the federal requirement; complete records are your only defence in an audit.", "sources": "https://www.canada.ca/en/revenue-agency/news/cra-multimedia-library/businesses-video-gallery/managing-books-and-records.html", "notes": "", "urls": ["https://www.canada.ca/en/revenue-agency/news/cra-multimedia-library/businesses-video-gallery/managing-books-and-records.html"]}, {"id": "26-008", "chapter_num": 26, "chapter_title": "Running a website or platform", "chapter_file": "26-running-a-website.md", "number": 8, "title": "Run notice-and-notice for user-uploaded content", "money": "0", "time": "mid", "willpower": "no", "benefit": "low", "dimension": "freedom", "evidence": "B", "grade": "B", "disputed": false, "cost": "No money; a working contact address and a forwarding procedure.", "plain": "When a copyright owner complains about user content, forward the notice to the user and keep records. You are a mailbox, not a judge.", "benefit_text": "Following the statutory procedure in sections 41.25 and 41.26 of the Copyright Act keeps you inside the safe harbour instead of inside the dispute.", "sources": "https://laws-lois.justice.gc.ca/pdf/c-42.pdf", "notes": "", "urls": ["https://laws-lois.justice.gc.ca/pdf/c-42.pdf"]}, {"id": "26-009", "chapter_num": 26, "chapter_title": "Running a website or platform", "chapter_file": "26-running-a-website.md", "number": 9, "title": "You stay responsible for data you send to foreign hosts", "money": "0", "time": "low", "willpower": "no", "benefit": "low", "dimension": "freedom", "evidence": "B", "grade": "B", "disputed": false, "cost": "No money; contract clauses and knowing where your servers actually are.", "plain": "Hosting in another country does not move your privacy obligations with it. You remain accountable for personal data your processors handle abroad.", "benefit_text": "Avoids a Commissioner finding that your cross-border transfers lacked comparable protection.", "sources": "https://www.priv.gc.ca/media/2038/guide_org_e.pdf?irpid=", "notes": "", "urls": ["https://www.priv.gc.ca/media/2038/guide_org_e.pdf?irpid="]}, {"id": "26-010", "chapter_num": 26, "chapter_title": "Running a website or platform", "chapter_file": "26-running-a-website.md", "number": 10, "title": "A .ca domain requires a Canadian presence", "money": "low", "time": "low", "willpower": "no", "benefit": "low", "dimension": "time", "evidence": "B", "grade": "B", "disputed": false, "cost": "The registration fee; a few minutes to confirm you meet the presence rules.", "plain": "CIRA only registers .ca names to people and organizations with a real Canadian connection — citizen, permanent resident, registered business, and similar categories.", "benefit_text": "Avoids losing a domain later for failing requirements you could have checked in minutes.", "sources": "https://www.cira.ca/en/resources/documents/domains/canadian-presence-requirements-registrants/", "notes": "", "urls": ["https://www.cira.ca/en/resources/documents/domains/canadian-presence-requirements-registrants/"]}, {"id": "26-011", "chapter_num": 26, "chapter_title": "Running a website or platform", "chapter_file": "26-running-a-website.md", "number": 11, "title": "There is no ICP-style licence for running a website in Canada", "money": "0", "time": "low", "willpower": "no", "benefit": "low", "dimension": "time", "evidence": "C", "grade": "C", "disputed": false, "cost": "No money; unlearning the assumption that a site needs government approval to exist.", "plain": "Nobody licences ordinary websites here. The real obligations are privacy, spam, tax, and copyright — items one through ten — not a permit to publish.", "benefit_text": "Saves the weeks some newcomers spend hunting for a non-existent approval.", "sources": "https://fintrac-canafe.canada.ca/public/businesses-entreprises-eng", "notes": "UNVERIFIED — negative regulatory claim, verified by absence across the primary sources above; see docs/verification/26-running-a-website.md.", "urls": ["https://fintrac-canafe.canada.ca/public/businesses-entreprises-eng"]}, {"id": "27-001", "chapter_num": 27, "chapter_title": "Pregnancy and childbirth", "chapter_file": "27-pregnancy-and-childbirth.md", "number": 1, "title": "Start folic acid before you start trying", "money": "low", "time": "low", "willpower": "some", "benefit": "high", "dimension": "death", "evidence": "A", "grade": "A", "disputed": false, "cost": "A few dollars a month for the supplement. The hard part is starting before conception, when pregnancy is still a plan.", "plain": "Folic acid prevents most neural-tube defects — the early-pregnancy faults that damage the baby's brain and spine. The dose is tiny, the cost is tiny, and it has to be in your blood before conception, because the neural tube closes in the first weeks, often before you know you are pregnant.", "benefit_text": "A Cochrane review: periconceptional folate supplementation cut neural-tube defects (RR 0.31, 95% CI 0.17 to 0.58); the standard dose is 0.4 mg daily, starting at least one month before conception. DOI 10.1002/14651858.CD007950.pub3.", "sources": "https://doi.org/10.1002/14651858.CD007950.pub3 ; figures verified 2026-10-01 on the Cochrane evidence summary (RR 0.31, 95% CI 0.17 to 0.58; five trials; 6708 births; high quality evidence): https://www.cochrane.org/evidence/CD007950_folic-acid-supplements-conception-and-early-pregnancy-12-weeks-prevention-birth-defects", "notes": "", "urls": ["https://doi.org/10.1002/14651858.CD007950.pub3", "https://www.cochrane.org/evidence/CD007950_folic-acid-supplements-conception-and-early-pregnancy-12-weeks-prevention-birth-defects"]}, {"id": "27-002", "chapter_num": 27, "chapter_title": "Pregnancy and childbirth", "chapter_file": "27-pregnancy-and-childbirth.md", "number": 2, "title": "Take the first-visit screening panel — infections included", "money": "0", "time": "low", "willpower": "no", "benefit": "high", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "Free as part of prenatal care; one blood draw at the first visit.", "plain": "At the first prenatal visit, the standard panel screens for infections that can pass to the baby: HIV, syphilis, hepatitis B, and others the province adds. They are treatable in pregnancy, which is exactly why the test comes first.", "benefit_text": "Ontario's sexual-health clinics offer free, confidential STI testing and treatment, anonymous HIV testing, and hepatitis A and B immunizations — no health card required. (The cited page does not describe a prenatal screening panel; ask the prenatal provider which infections the first-visit panel covers.) Treating syphilis or HIV in pregnancy sharply cuts transmission to the newborn.", "sources": "http://www.ontario.ca/page/sexual-health-clinics", "notes": "", "urls": ["http://www.ontario.ca/page/sexual-health-clinics"]}, {"id": "27-003", "chapter_num": 27, "chapter_title": "Pregnancy and childbirth", "chapter_file": "27-pregnancy-and-childbirth.md", "number": 3, "title": "Take no alcohol and no smoking through the whole pregnancy", "money": "0", "time": "low", "willpower": "yes", "benefit": "high", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "Free. It costs willpower, especially if quitting smoking is part of the deal — ask the doctor for help with that.", "plain": "Alcohol in pregnancy can cause lifelong brain damage; there is no known safe amount. Smoking raises the risk of miscarriage, early birth, and sudden infant death. Both do their damage quietly, long before any test can catch it.", "benefit_text": "The Public Health Agency of Canada: \"There is no safe amount or safe time to drink alcohol during pregnancy.\" On smoking the cited PHAC page says only: \"If you are currently smoking the best step you can take is to quit!\" — the specific smoking-harm list (miscarriage, preterm birth, low birth weight, SIDS) is standard obstetric guidance but is not stated on the cited page; see docs/verification/spot-read.md.", "sources": "https://phac-aspc.gc.ca/hp-gs/calendar/comp_calendar-eng.php?d=02/28/2023&m=1", "notes": "", "urls": ["https://phac-aspc.gc.ca/hp-gs/calendar/comp_calendar-eng.php?d=02/28/2023&m=1"]}, {"id": "27-004", "chapter_num": 27, "chapter_title": "Pregnancy and childbirth", "chapter_file": "27-pregnancy-and-childbirth.md", "number": 4, "title": "Ask about low-dose aspirin if you are at high risk of preeclampsia", "money": "low", "time": "low", "willpower": "no", "benefit": "high", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "A few dollars a month — but only on a doctor's prescription, never self-started.", "plain": "Preeclampsia — dangerously high blood pressure in pregnancy — can be blunted with a small daily dose of aspirin started after the twelfth week, but only for women whose risk is already high: previous preeclampsia, twins, chronic hypertension, diabetes, and a few other flags. This is a prescription conversation, not a do-it-yourself one.", "benefit_text": "The US Preventive Services Task Force, 2021: low-dose aspirin (81 mg per day) from 12 weeks for high-risk women reduced preeclampsia (RR 0.85), preterm birth (RR 0.80), and related harms.", "sources": "https://www.uspreventiveservicestaskforce.org/uspstf/recommendation/low-dose-aspirin-use-for-the-prevention-of-morbidity-and-mortality-from-preeclampsia-preventive-medication", "notes": "", "urls": ["https://www.uspreventiveservicestaskforce.org/uspstf/recommendation/low-dose-aspirin-use-for-the-prevention-of-morbidity-and-mortality-from-preeclampsia-preventive-medication"]}, {"id": "27-005", "chapter_num": 27, "chapter_title": "Pregnancy and childbirth", "chapter_file": "27-pregnancy-and-childbirth.md", "number": 5, "title": "Take the diabetes test at 24 to 28 weeks", "money": "0", "time": "low", "willpower": "no", "benefit": "high", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "Free as part of prenatal care; one sugary drink and a couple of hours at the lab.", "plain": "Pregnancy can unmask diabetes even in women who never had it. The sugar-drink test between the twenty-fourth and twenty-eighth week catches it; caught, it is managed with diet, monitoring, and medication when needed. Missed, it overfeeds the baby and complicates the birth.", "benefit_text": "Diabetes Canada: screen for gestational diabetes at 24–28 weeks of pregnancy; untreated gestational diabetes raises the risk of a large baby, birth injury, and later type 2 diabetes in the mother.", "sources": "https://www.healthlinkbc.ca/healthwise/screening-gestational-diabetes and https://reference.medscape.com/calculator/547/screening-for-and-diagnosing-gestational-diabetes-mellitus-gdm", "notes": "", "urls": ["https://reference.medscape.com/calculator/547/screening-for-and-diagnosing-gestational-diabetes-mellitus-gdm", "https://www.healthlinkbc.ca/healthwise/screening-gestational-diabetes"]}, {"id": "27-006", "chapter_num": 27, "chapter_title": "Pregnancy and childbirth", "chapter_file": "27-pregnancy-and-childbirth.md", "number": 6, "title": "Learn the warning signs that mean \"go now\"", "money": "0", "time": "low", "willpower": "no", "benefit": "high", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "Free to learn. Acting on them costs an emergency visit — which is the point.", "plain": "The CDC's Hear Her campaign lists the red flags from pregnancy through one year after birth: a severe headache that will not shift, vision changes, chest pain, trouble breathing, heavy bleeding, a gush of fluid, fever of 38 degrees and up, and thoughts of harming yourself. Any one of them means call 911, get to the emergency department — do not wait for the next appointment.", "benefit_text": "The CDC Hear Her campaign: urgent maternal warning signs during pregnancy and up to 1 year postpartum include severe headache, vision changes, chest pain, difficulty breathing, heavy vaginal bleeding or fluid leaking, fever of 38°C (100.4°F) or higher, and thoughts of self-harm; any of these warrants calling 911 or going to the emergency department immediately.", "sources": "https://www.cdc.gov/hearher/news-media/article-urgent-warning-signs.html?CDC_AAref_Val=https://www.cdc.gov/hearher/resources/news-media/recognizing-urgent-warning-signs.html", "notes": "", "urls": ["https://www.cdc.gov/hearher/news-media/article-urgent-warning-signs.html?CDC_AAref_Val=https://www.cdc.gov/hearher/resources/news-media/recognizing-urgent-warning-signs.html"]}, {"id": "27-007", "chapter_num": 27, "chapter_title": "Pregnancy and childbirth", "chapter_file": "27-pregnancy-and-childbirth.md", "number": 7, "title": "Ask for the epidural when you need it — it does not force a C-section", "money": "0", "time": "low", "willpower": "no", "benefit": "mid", "dimension": "freedom", "evidence": "A", "grade": "A", "disputed": false, "cost": "Free as part of hospital birth in Canada. It costs nothing but the asking.", "plain": "Fear of the epidural often rests on the belief that it leads to surgery. Pooled trials found no rise in C-section rates with epidurals. Labour still gets longer and an assisted vaginal birth gets likelier, but the C-section link is not there.", "benefit_text": "A Cochrane review (2018, 40+ trials): \"Epidural analgesia had no impact on the risk of caesarean section\" (low-quality evidence); epidurals lengthened labour and raised the chance of assisted vaginal birth in older trials, an effect not seen with modern low-dose techniques.", "sources": "https://www.cochrane.org/CD000331", "notes": "", "urls": ["https://www.cochrane.org/CD000331"]}, {"id": "27-008", "chapter_num": 27, "chapter_title": "Pregnancy and childbirth", "chapter_file": "27-pregnancy-and-childbirth.md", "number": 8, "title": "Do not book a C-section for convenience", "money": "0", "time": "low", "willpower": "some", "benefit": "mid", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "Free to avoid. It costs resisting the temptation of a scheduled date.", "plain": "A C-section is major surgery with real recovery costs and real risks for later pregnancies. The World Health Organization finds no mortality benefit once national rates pass ten percent — the operation saves lives when it is needed, not when it is scheduled for the calendar.", "benefit_text": "The WHO 2015 statement: caesarean rates above 10% at population level are not associated with lower maternal or newborn mortality; C-sections should be provided to women in need, not pursued to hit target rates.", "sources": "https://www.who.int/news/item/09-04-2015-caesarean-sections-should-only-be-performed-when-medically-necessary-says-who", "notes": "", "urls": ["https://www.who.int/news/item/09-04-2015-caesarean-sections-should-only-be-performed-when-medically-necessary-says-who"]}, {"id": "27-009", "chapter_num": 27, "chapter_title": "Pregnancy and childbirth", "chapter_file": "27-pregnancy-and-childbirth.md", "number": 9, "title": "File for EI or QPIP — never both", "money": "0", "time": "mid", "willpower": "no", "benefit": "high", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "Free to apply. It costs paperwork and waiting.", "plain": "Outside Quebec, maternity and parental benefits come from federal employment insurance: fifteen weeks for the birth parent plus parental weeks to share. In Quebec, the provincial plan replaces EI entirely — Quebec residents claim QPIP, not EI. The two systems do not stack.", "benefit_text": "2026 EI figures: maternity and standard parental benefits pay 55% of average insurable weekly earnings, up to $729 a week; extended parental pays 33%, up to $437 a week; 600 insurable hours are required. Quebec residents are ineligible for EI maternity and parental benefits and claim the Quebec Parental Insurance Plan instead; the two programs are mutually exclusive.", "sources": "https://www.canada.ca/en/services/benefits/ei/ei-maternity-parental/benefit-amount.html and https://www.rqap.gouv.qc.ca/en", "notes": "", "urls": ["https://www.canada.ca/en/services/benefits/ei/ei-maternity-parental/benefit-amount.html", "https://www.rqap.gouv.qc.ca/en"]}, {"id": "27-010", "chapter_num": 27, "chapter_title": "Pregnancy and childbirth", "chapter_file": "27-pregnancy-and-childbirth.md", "number": 10, "title": "Register the birth and get the baby's health card in the first days", "money": "0", "time": "low", "willpower": "no", "benefit": "high", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "Free; birth registration and the newborn health card application cost nothing in Ontario.", "plain": "Do the paperwork before the baby arrives if you can: Ontario's newborn bundle files the birth registration, the birth certificate, the baby's health card, and the federal benefit applications in one sitting. A baby with a health card from day one never hits a billing surprise.", "benefit_text": "ServiceOntario's 5-in-1 Newborn Bundle: birth registration, birth certificate order, OHIP application, and federal child-benefit applications in one session; hospitals issue the infant registration form with the baby's preprinted health number.", "sources": "http://www.ontario.ca/page/serviceontario", "notes": "", "urls": ["http://www.ontario.ca/page/serviceontario"]}, {"id": "27-011", "chapter_num": 27, "chapter_title": "Pregnancy and childbirth", "chapter_file": "27-pregnancy-and-childbirth.md", "number": 11, "title": "Say yes to newborn screening", "money": "0", "time": "low", "willpower": "no", "benefit": "high", "dimension": "death", "evidence": "C", "grade": "C", "disputed": false, "cost": "Free, done in the hospital before discharge.", "plain": "A few drops of blood from the baby's heel in the first days screen for a panel of rare but treatable diseases — plus hearing and heart checks in most provinces. The diseases are rare; the treatments only work when they start before symptoms.", "benefit_text": "Ontario's Newborn Screening program tests every newborn's blood spot for 6 groups of diseases, plus screening for critical heart disease, biliary atresia, and hearing loss; other provinces run their own programs with similar panels. Early treatment prevents brain damage and death.", "sources": "http://www.newbornscreening.on.ca/en/screening/diseases-screened/", "notes": "", "urls": ["http://www.newbornscreening.on.ca/en/screening/diseases-screened/"]}, {"id": "27-012", "chapter_num": 27, "chapter_title": "Pregnancy and childbirth", "chapter_file": "27-pregnancy-and-childbirth.md", "number": 12, "title": "Keep the six-week postpartum check — and watch blood pressure in the first week", "money": "0", "time": "low", "willpower": "no", "benefit": "high", "dimension": "death", "evidence": "C", "grade": "C", "disputed": false, "cost": "Free as part of postpartum care; one appointment.", "plain": "The six-week visit is where the doctor checks healing, mood, blood pressure, and birth control. Before that, the riskiest window for blood pressure spikes is the first days at home — midwives check around day three to six. Call sooner if headaches, swelling, vision changes show up.", "benefit_text": "The Public Health Agency of Canada's maternity and newborn care guidelines: blood pressure should be checked 3 to 6 days after birth; midwifery care typically ends around 6 weeks with a final visit covering physical recovery, mental health, and contraception.", "sources": "https://www.canada.ca/en/public-health/services/publications/healthy-living/maternity-newborn-care-guidelines-chapter-5.html and https://www.midwivesofmississauga.ca/care-we-provide/postpartum/", "notes": "", "urls": ["https://www.canada.ca/en/public-health/services/publications/healthy-living/maternity-newborn-care-guidelines-chapter-5.html", "https://www.midwivesofmississauga.ca/care-we-provide/postpartum/"]}, {"id": "28-001", "chapter_num": 28, "chapter_title": "Don't wreck your health for looks", "chapter_file": "28-health-vs-looks.md", "number": 1, "title": "Do not starve yourself thin — extreme dieting breeds eating disorders", "money": "0", "time": "low", "willpower": "yes", "benefit": "high", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "Free. It costs the willpower to eat normally in a culture that praises thinness.", "plain": "Crash diets do not just fail; they teach the brain the binge-restrict cycle. In a long-term study of teenage girls, severe dieters developed eating disorders at eighteen times the rate of non-dieters, moderate dieters at five times the rate. Exercise controls weight more safely than hunger does.", "benefit_text": "Patton et al., 1999: 14–15-year-old girls followed for 3 years; severe dieting predicted eating disorders 18-fold, moderate dieting 5-fold. Arcelus et al., 2011, meta-analysis: anorexia nervosa carries a standardized mortality ratio of 5.86 — among the highest of any psychiatric disorder.", "sources": "https://pmc.ncbi.nlm.nih.gov/articles/PMC27789/ and https://pubmed.ncbi.nlm.nih.gov/21727255/", "notes": "", "urls": ["https://pmc.ncbi.nlm.nih.gov/articles/PMC27789/", "https://pubmed.ncbi.nlm.nih.gov/21727255/"]}]);
